arguments.file_text:
@page "/catalog"
@using sv_0125ab9853c1472490b4cfcc1d27d64a.Services
@rendermode InteractiveServer
@inject IProductService ProductService

<PageTitle>Product Catalog</PageTitle>

<h1 class="mb-4">Product Catalog</h1>

@if (isLoading && products is null)
{
    <div class="d-flex justify-content-center py-5">
        <div class="spinner-border text-primary" role="status">
            <span class="visually-hidden">Loading...</span>
        </div>
    </div>
}
else if (errorMessage is not null)
{
    <div class="alert alert-danger" role="alert">
        <strong>Error:</strong> @errorMessage
        <button class="btn btn-outline-danger btn-sm ms-3" @onclick="RetryAsync">Retry</button>
    </div>
}
else
{
    <div class="catalog-layout">
        <!-- Sidebar Filters -->
        <aside class="catalog-sidebar">
            <h5>Filters</h5>

            @if (categories is not null && categories.Count > 0)
            {
                <div class="filter-section">
                    <h6>Category</h6>
                    @foreach (var category in categories)
                    {
                        <div class="form-check">
                            <input class="form-check-input" type="checkbox" id="@($"cat-{category}")"
                                   checked="@selectedCategories.Contains(category)"
                                   @onchange="@(e => ToggleCategory(category, (bool)(e.Value ?? false)))" />
                            <label class="form-check-label" for="@($"cat-{category}")">@category</label>
                        </div>
                    }
                </div>
            }

            <div class="filter-section">
                <h6>Price Range</h6>
                <div class="mb-2">
                    <label for="minPrice" class="form-label form-label-sm">Min Price</label>
                    <input id="minPrice" type="number" class="form-control form-control-sm"
                           min="0" step="0.01" placeholder="Min"
                           @bind="minPrice" />
                </div>
                <div class="mb-2">
                    <label for="maxPrice" class="form-label form-label-sm">Max Price</label>
                    <input id="maxPrice" type="number" class="form-control form-control-sm"
                           min="0" step="0.01" placeholder="Max"
                           @bind="maxPrice" />
                </div>
            </div>

            <div class="filter-section">
                <div class="form-check">
                    <input class="form-check-input" type="checkbox" id="inStockOnly"
                           @bind="inStockOnly" />
                    <label class="form-check-label" for="inStockOnly">In Stock Only</label>
                </div>
            </div>

            <div class="d-grid gap-2 mt-3">
                <button class="btn btn-primary btn-sm" @onclick="ApplyFiltersAsync" disabled="@isLoading">
                    Apply Filters
                </button>
                <button class="btn btn-outline-secondary btn-sm" @onclick="ClearFiltersAsync" disabled="@isLoading">
                    Clear Filters
                </button>
            </div>
        </aside>

        <!-- Main Content -->
        <section class="catalog-main">
            <!-- Toolbar -->
            <div class="catalog-toolbar">
                <div class="d-flex align-items-center gap-2">
                    <label for="sortBy" class="form-label mb-0 text-nowrap">Sort by:</label>
                    <select id="sortBy" class="form-select form-select-sm sort-select" @bind="sortBy"
                            @bind:after="OnSortChangedAsync">
                        <option value="price_asc">Price: Low to High</option>
                        <option value="price_desc">Price: High to Low</option>
                        <option value="name_asc">Name: A-Z</option>
                        <option value="rating_desc">Rating: Highest</option>
                    </select>
                </div>
                <span class="text-muted showing-label">
                    @if (products is not null && totalCount > 0)
                    {
                        var start = (currentPage - 1) * pageSize + 1;
                        var end = Math.Min(currentPage * pageSize, totalCount);
                        @($"Showing {start}–{end} of {totalCount} products")
                    }
                </span>
            </div>

            @if (isLoading)
            {
                <div class="d-flex justify-content-center py-5">
                    <div class="spinner-border text-primary" role="status">
                        <span class="visually-hidden">Loading...</span>
                    </div>
                </div>
            }
            else if (products is not null && products.Count == 0)
            {
                <div class="alert alert-info text-center my-5" role="status">
                    No products found matching your filters. Try adjusting your criteria.
                </div>
            }
            else if (products is not null)
            {
                <!-- Product Grid -->
                <div class="product-grid">
                    @foreach (var product in products)
                    {
                        <ProductCard Product="product"
                                     OnSelected="OnProductSelected"
                                     OnAddToCart="OnAddToCart" />
                    }
                </div>

                <!-- Pagination -->
                @if (totalPages > 1)
                {
                    <nav aria-label="Product pagination" class="mt-4">
                        <ul class="pagination justify-content-center">
                            <li class="page-item @(currentPage <= 1 ? "disabled" : "")">
                                <button class="page-link" @onclick="@(() => GoToPageAsync(currentPage - 1))"
                                        disabled="@(currentPage <= 1)">
                                    Previous
                                </button>
                            </li>
                            @foreach (var p in GetPageNumbers())
                            {
                                <li class="page-item @(p == currentPage ? "active" : "")">
                                    <button class="page-link" @onclick="@(() => GoToPageAsync(p))">@p</button>
                                </li>
                            }
                            <li class="page-item @(currentPage >= totalPages ? "disabled" : "")">
                                <button class="page-link" @onclick="@(() => GoToPageAsync(currentPage + 1))"
                                        disabled="@(currentPage >= totalPages)">
                                    Next
                                </button>
                            </li>
                        </ul>
                    </nav>
                }
            }
        </section>
    </div>
}

@code {
    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    [Parameter]
    public EventCallback<Product> OnAddToCart { get; set; }

    private List<Product>? products;
    private List<string>? categories;
    private bool isLoading = true;
    private string? errorMessage;

    // Filter state
    private HashSet<string> selectedCategories = new();
    private decimal? minPrice;
    private decimal? maxPrice;
    private bool inStockOnly;

    // Sort & pagination
    private string sortBy = "price_asc";
    private int currentPage = 1;
    private int pageSize = 12;
    private int totalCount;
    private int totalPages;

    protected override async Task OnInitializedAsync()
    {
        await LoadInitialDataAsync();
    }

    private async Task LoadInitialDataAsync()
    {
        isLoading = true;
        errorMessage = null;

        try
        {
            var categoriesTask = ProductService.GetCategoriesAsync();
            var productsTask = SearchProductsAsync();

            categories = await categoriesTask;
            await productsTask;
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load catalog: {ex.Message}";
        }
        finally
        {
            isLoading = false;
        }
    }

    private async Task SearchProductsAsync()
    {
        var filter = new ProductFilter(
            Categories: selectedCategories.Count > 0 ? selectedCategories.ToList() : null,
            MinPrice: minPrice,
            MaxPrice: maxPrice,
            InStockOnly: inStockOnly
        );

        var result = await ProductService.SearchAsync(filter, sortBy, currentPage, pageSize);

        products = result.Items;
        totalCount = result.TotalCount;
        currentPage = result.Page;
        totalPages = (int)Math.Ceiling((double)result.TotalCount / result.PageSize);
    }

    private async Task ApplyFiltersAsync()
    {
        currentPage = 1;
        isLoading = true;
        errorMessage = null;

        try
        {
            await SearchProductsAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Search failed: {ex.Message}";
        }
        finally
        {
            isLoading = false;
        }
    }

    private async Task ClearFiltersAsync()
    {
        selectedCategories.Clear();
        minPrice = null;
        maxPrice = null;
        inStockOnly = false;
        currentPage = 1;

        await ApplyFiltersAsync();
    }

    private async Task OnSortChangedAsync()
    {
        currentPage = 1;
        await ApplyFiltersAsync();
    }

    private async Task GoToPageAsync(int page)
    {
        if (page < 1 || page > totalPages || page == currentPage)
            return;

        currentPage = page;
        isLoading = true;
        errorMessage = null;

        try
        {
            await SearchProductsAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load page: {ex.Message}";
        }
        finally
        {
            isLoading = false;
        }
    }

    private async Task RetryAsync()
    {
        await LoadInitialDataAsync();
    }

    private void ToggleCategory(string category, bool isChecked)
    {
        if (isChecked)
            selectedCategories.Add(category);
        else
            selectedCategories.Remove(category);
    }

    private IEnumerable<int> GetPageNumbers()
    {
        const int maxVisible = 5;

        int start = Math.Max(1, currentPage - maxVisible / 2);
        int end = Math.Min(totalPages, start + maxVisible - 1);
        start = Math.Max(1, end - maxVisible + 1);

        return Enumerable.Range(start, end - start + 1);
    }
}

.catalog-layout {
    display: flex;
    gap: 1.5rem;
}

.catalog-sidebar {
    flex: 0 0 25%;
    max-width: 25%;
    background: #f8f9fa;
    border-radius: 8px;
    padding: 1.25rem;
    align-self: flex-start;
    position: sticky;
    top: 1rem;
}

.catalog-main {
    flex: 1;
    min-width: 0;
}

.filter-section {
    margin-bottom: 1rem;
    padding-bottom: 1rem;
    border-bottom: 1px solid #dee2e6;
}

.filter-section h6 {
    margin-bottom: 0.5rem;
    font-weight: 600;
}

.catalog-toolbar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1rem;
    padding: 0.75rem 1rem;
    background: #f8f9fa;
    border-radius: 6px;
    flex-wrap: wrap;
    gap: 0.5rem;
}

.sort-select {
    width: auto;
    min-width: 200px;
}

.showing-label {
    font-size: 0.9rem;
}

.product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
    gap: 1.25rem;
}

@media (max-width: 768px) {
    .catalog-layout {
        flex-direction: column;
    }

    .catalog-sidebar {
        flex: none;
        max-width: 100%;
        position: static;
    }

    .product-grid {
        grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
    }
}

