                           @bind="minPrice" />
                </div>
                <div class="mb-2">
                    <label for="maxPrice" class="form-label form-label-sm">Max Price</label>
                    <input id="maxPrice" type="number" class="form-control form-control-sm"
                           min="0" step="0.01" placeholder="Max"
                           @bind="maxPrice" />
                </div>
            </div>

            <div class="filter-section">
                <div class="form-check">
                    <input class="form-check-input" type="checkbox" id="inStockOnly"
                           @bind="inStockOnly" />
                    <label class="form-check-label" for="inStockOnly">In Stock Only</label>
                </div>
            </div>

