+.catalog-layout {
+    display: flex;
+    gap: 1.5rem;
+}
+
+.catalog-sidebar {
+    flex: 0 0 25%;
+    max-width: 25%;
+    background: #f8f9fa;
+    border-radius: 8px;
+    padding: 1.25rem;
+    align-self: flex-start;
+    position: sticky;
+    top: 1rem;
+}
+
+.catalog-main {
+    flex: 1;
+    min-width: 0;
+}
+
+.filter-section {
+    margin-bottom: 1rem;
+    padding-bottom: 1rem;
+    border-bottom: 1px solid #dee2e6;
+}
+
+.filter-section h6 {
+    margin-bottom: 0.5rem;
+    font-weight: 600;
+}
+
+.catalog-toolbar {
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+    margin-bottom: 1rem;
+    padding: 0.75rem 1rem;
+    background: #f8f9fa;
+    border-radius: 6px;
+    flex-wrap: wrap;
+    gap: 0.5rem;
+}
+
+.sort-select {
+    width: auto;
+    min-width: 200px;
+}
+
+.showing-label {
+    font-size: 0.9rem;
+}
+
+.product-grid {
+    display: grid;
+    grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
+    gap: 1.25rem;
+}
+
+@media (max-width: 768px) {
+    .catalog-layout {
+        flex-direction: column;
+    }
+
+    .catalog-sidebar {
+        flex: none;
+        max-width: 100%;
+        position: static;
+    }
+
+    .product-grid {
+        grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
+    }
+}
+
